<script setup lang="ts">
import {confirmAction,promptAction} from '../ui/confirm'
import { ref,computed,onMounted } from 'vue'
import { request } from '../api'
import SnapshotView from './SnapshotView.vue'
const data=ref<any>({items:[],total:0}),types=ref<any[]>([]),q=ref(''),type=ref(''),page=ref(1),selected=ref<string[]>([]),detail=ref<any>(null),results=ref<any[]>([]),busy=ref(false),error=ref(''),media=ref<any[]>([])
const pages=computed(()=>Math.max(1,Math.ceil(data.value.total/20)))
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function load(){const params=new URLSearchParams({page:String(page.value),q:q.value});if(type.value)params.set('type_id',type.value);data.value=await request('/admin/recovery/trash?'+params);selected.value=[];media.value=await request('/admin/recovery/media')}
async function inspect(id:string){detail.value=await request('/admin/recovery/trash/'+id)}
async function act(action:'restore'|'purge',single?:any){const rows=single?[single]:data.value.items.filter((r:any)=>selected.value.includes(r.id));if(!rows.length)return;if(!await confirmAction(action==='restore'?'恢复所选记录及保留的关联？':'永久删除所选文章、历史和专属关联，无法通过回收站恢复。共享媒体原图、地点和模板保留。确定吗？'))return;if(action==='purge'&&await promptAction('不可撤销。请输入“永久删除”再次确认。')!=='永久删除')return;void run(async()=>{const r=await request('/admin/recovery/trash/'+action,{method:'POST',body:JSON.stringify({items:rows.map((r:any)=>({id:r.id,expected_revision:r.revision})),confirmation:action==='restore'?'恢复':'永久删除'})});results.value=r.items;detail.value=null;await load()})}
async function restoreMedia(m:any){if(!await confirmAction('恢复此媒体索引？不会修改原图文件。'))return;void run(async()=>{await request('/admin/recovery/media/'+m.id+'/restore',{method:'POST',body:JSON.stringify({expected_revision:m.revision})});await load()})}
onMounted(()=>void run(async()=>{types.value=await request('/admin/content/types');await load()}))
</script>
<template><main class="container trash-admin"><h1>回收站</h1><p>软删除保留正文、历史与关联。默认保留期30天；须在“备份与恢复”审核并确认策略后才启用自动清理。永久删除不删除媒体库原图、共享地点或模板。</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="busy" role="status">正在处理…</p><section v-if="results.length" class="notice" role="status"><p v-for="r in results" :key="r.id">{{r.state==='failed'?r.error:r.state==='restored'?'记录已恢复':r.state==='already_active'?'记录已恢复过，本次未重复修改':r.state==='purged'?'记录已永久删除':'记录已永久删除过'}}<span v-for="w in r.warnings||[]" :key="w"> · {{w}}</span></p></section><form class="card trash-filters" @submit.prevent="page=1;run(load)"><label>搜索删除的标题<input v-model="q" maxlength="200" type="search"/></label><label>回收站内容类型<select v-model="type" aria-label="回收站内容类型"><option value="">全部类型</option><option v-for="t in types" :key="t.id" :value="t.id">{{t.name}}</option></select></label><button :disabled="busy">查找删除记录</button></form><div class="actions"><button :disabled="busy||!selected.length" @click="act('restore')">恢复所选</button><button class="danger" :disabled="busy||!selected.length" @click="act('purge')">永久删除所选</button><span>已选 {{selected.length}} 篇（当前页）</span></div><section class="card"><p v-if="!data.items.length" class="muted">回收站为空。</p><article v-for="r in data.items" :key="r.id" class="trash-row"><label class="checks"><input v-model="selected" type="checkbox" :value="r.id" :aria-label="'选择 '+r.title"/><strong>{{r.title}}</strong></label><p>{{r.type_name}} · 删除于 {{r.deleted_at}} · 创建于 {{r.created_at}}</p><div class="actions"><button class="quiet" :disabled="busy" @click="run(()=>inspect(r.id))">查看删除记录</button><button :disabled="busy" @click="act('restore',r)">恢复记录</button><button class="danger" :disabled="busy" @click="act('purge',r)">永久删除记录</button><a :href="'/admin/history/'+r.id">历史版本</a></div></article><div class="actions"><button :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><span>{{page}} / {{pages}} · {{data.total}} 篇 · 按删除时间倒序</span><button :disabled="busy||page>=pages" @click="page++;run(load)">下一页</button></div></section><section v-if="detail" class="card"><h2>删除记录信息</h2><p v-for="w in detail.warnings" :key="w" class="notice">{{w}}</p><SnapshotView :value="detail"/></section><details class="card"><summary>已停用媒体索引（仅恢复，不删除文件）</summary><p v-if="!media.length">没有可恢复的媒体索引。</p><div v-for="m in media" :key="m.id" class="trash-row"><p>{{m.title||m.filename}} · {{m.deleted_at}}</p><button :disabled="busy" @click="restoreMedia(m)">恢复媒体索引</button></div></details></main></template>
<style scoped>.trash-filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap}.trash-filters label{flex:1;min-width:180px}.trash-filters button{margin-bottom:15px}.trash-admin>.card{margin-block:20px}.trash-row{padding:18px 0;border-bottom:1px solid var(--ui-line);overflow-wrap:anywhere}.trash-row input{width:auto;margin:0}.trash-row p{font-size:14px}.trash-admin summary{cursor:pointer;min-height:44px}@media(max-width:600px){.trash-filters{display:block}.trash-admin .actions{align-items:stretch}.trash-admin .actions button{min-height:44px}}
</style>
